/* ===== Global background & fonts ===== */
QMainWindow, QWidget {
    background-color: #F5F6FA;
    color: #263238;
    font-family: "Microsoft YaHei", "微软雅黑";
    font-size: 13px;
}

/* ===== Card containers ===== */
QFrame#card, QFrame#cardHeader, QFrame#cardToolbar {
    background-color: #FFFFFF;
    border: 1px solid #E0E0E0;
    border-radius: 8px;
}

/* ===== Button base style - uniform light green ===== */
QPushButton {
    color: #FFFFFF;
    border: none;
    border-radius: 6px;
    padding: 5px 10px;
    font-size: 13px;
    font-family: "Microsoft YaHei", "微软雅黑";
    text-align: center;
    min-width: 70px;
    background-color: #66BB6A;
}
QPushButton:hover {
    background-color: #4CAF50;
}
QPushButton:pressed {
    background-color: #388E3C;
}
QPushButton:disabled {
    background-color: #BDBDBD;
    color: #EEEEEE;
}

/* ===== Checkboxes & labels ===== */
QCheckBox, QLabel {
    font-family: "Microsoft YaHei", "微软雅黑";
    font-size: 12px;
    color: #263238;
    background: transparent;
}
QCheckBox::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #BDBDBD;
    border-radius: 3px;
    background-color: #FFFFFF;
}
QCheckBox::indicator:hover {
    border: 1px solid #1976D2;
}
QCheckBox::indicator:checked {
    background-color: #1976D2;
    border: 1px solid #1976D2;
}

/* ===== Table ===== */
QTableWidget {
    background-color: #FFFFFF;
    alternate-background-color: #FAFAFA;
    border: 1px solid #E0E0E0;
    border-radius: 4px;
    gridline-color: #E0E0E0;
    selection-background-color: #BBDEFB;
    selection-color: #263238;
    font-size: 13px;
    outline: none;
}
QTableWidget::item {
    padding: 5px 4px;
}
QTableWidget::item:selected {
    background-color: #BBDEFB;
    color: #263238;
}
QHeaderView::section {
    background-color: #1976D2;
    color: #FFFFFF;
    padding: 8px 6px;
    border: none;
    border-right: 1px solid #1565C0;
    font-weight: bold;
    font-size: 13px;
}
QHeaderView::section:hover {
    background-color: #1565C0;
}
QHeaderView::section:last {
    border-right: none;
}
QTableCornerButton::section {
    background-color: #1976D2;
    border: none;
}

/* ===== Tabs ===== */
QTabWidget::pane {
    border: 1px solid #E0E0E0;
    border-top: none;
    border-radius: 0 0 8px 8px;
    background-color: #FFFFFF;
    top: -1px;
}
QTabBar::tab {
    background-color: #F5F6FA;
    color: #757575;
    padding: 8px 20px;
    border: 1px solid #E0E0E0;
    border-bottom: none;
    border-top-left-radius: 6px;
    border-top-right-radius: 6px;
    margin-right: 2px;
    font-size: 13px;
    font-family: "Microsoft YaHei", "微软雅黑";
}
QTabBar::tab:selected {
    background-color: #FFFFFF;
    color: #1976D2;
    font-weight: bold;
}
QTabBar::tab:hover:!selected {
    background-color: #E3F2FD;
    color: #1976D2;
}

/* ===== Progress bar ===== */
QProgressBar {
    background-color: #E0E0E0;
    border: none;
    border-radius: 8px;
    text-align: center;
    color: #263238;
    font-size: 12px;
    min-height: 16px;
    max-height: 16px;
}
QProgressBar::chunk {
    background-color: #1976D2;
    border-radius: 8px;
}

/* ===== Input fields & dropdowns ===== */
QLineEdit, QComboBox {
    background-color: #FFFFFF;
    border: 1px solid #E0E0E0;
    border-radius: 4px;
    padding: 4px 6px;
    font-size: 13px;
    color: #263238;
    font-family: "Microsoft YaHei", "微软雅黑";
}
QLineEdit:focus, QComboBox:focus {
    border: 1px solid #1976D2;
}
QComboBox::drop-down {
    border: none;
    width: 22px;
}
QComboBox QAbstractItemView {
    background-color: #FFFFFF;
    border: 1px solid #E0E0E0;
    border-radius: 4px;
    selection-background-color: #BBDEFB;
    selection-color: #263238;
    padding: 4px;
    outline: none;
}

/* ===== Status bar ===== */
QStatusBar {
    background-color: #FFFFFF;
    border-top: 1px solid #E0E0E0;
    color: #616161;
    font-size: 12px;
}
QStatusBar::item {
    border: none;
}
QStatusBar QLabel {
    color: #616161;
}

/* ===== Menu ===== */
QMenu {
    background-color: #FFFFFF;
    border: 1px solid #E0E0E0;
    border-radius: 6px;
    padding: 4px;
    font-size: 13px;
}
QMenu::item {
    padding: 6px 24px;
    border-radius: 4px;
}
QMenu::item:selected {
    background-color: #BBDEFB;
    color: #1976D2;
}
QMenu::separator {
    height: 1px;
    background-color: #E0E0E0;
    margin: 4px 8px;
}

/* ===== Scrollbars ===== */
QScrollBar:vertical {
    background-color: #F5F6FA;
    width: 10px;
    border: none;
    margin: 0;
}
QScrollBar::handle:vertical {
    background-color: #BDBDBD;
    border-radius: 5px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background-color: #9E9E9E;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: none;
}
QScrollBar:horizontal {
    background-color: #F5F6FA;
    height: 10px;
    border: none;
    margin: 0;
}
QScrollBar::handle:horizontal {
    background-color: #BDBDBD;
    border-radius: 5px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background-color: #9E9E9E;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: none;
}

/* ===== Text edit ===== */
QTextEdit {
    background-color: #FFFFFF;
    border: 1px solid #E0E0E0;
    border-radius: 4px;
    font-family: "Microsoft YaHei", "微软雅黑";
    color: #263238;
    padding: 4px;
}
QTextEdit:focus {
    border: 1px solid #1976D2;
}

/* ===== Tooltip ===== */
QToolTip {
    background-color: #263238;
    color: #FFFFFF;
    border: none;
    border-radius: 4px;
    padding: 4px 8px;
    font-size: 12px;
}

